	private int findSlot(long hash, long mask) {
		int slot = PackedPrimitiveHash.slot(hash, tableSlots.length);
		while (true) {
			int stateId = tableSlots[slot];
			if (stateId == 0 || hashes[stateId] == hash && masks[stateId] == mask) {
				return slot;
			}
			slot = slot + 1 & tableSlots.length - 1;
		}
	}

